class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next


def arr_to_list(arr):
    head = None
    tail = None
    for v in arr:
        node = ListNode(v)
        if not head:
            head, tail = node, node
        else:
            tail.next = node
            tail = node
    return head


def list_to_arr(head):
    result = []
    node = head
    while node:
        result.append(node.val)
        node = node.next
    return result


def reverse_k_group(head_arr, k):
    head = arr_to_list(head_arr)
    dummy = ListNode(0, head)
    group_prev = dummy

    while True:
        kth = group_prev
        for _ in range(k):
            kth = kth.next
            if not kth:
                return list_to_arr(dummy.next)

        group_next = kth.next
        prev, curr = group_next, group_prev.next
        while curr is not group_next:
            nxt = curr.next
            curr.next = prev
            prev = curr
            curr = nxt

        new_group_head = prev
        old_group_head = group_prev.next
        group_prev.next = new_group_head
        group_prev = old_group_head

